INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ECC nur für Arbeitsspeicher gedacht?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Datenspeicherung"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Hauptfunktion hat ECC?', 3, '[{"text": "Fehlererkennung und -korrektur", "correct": true, "because": "Datenintegrität"}, {"text": "Datenverschlüsselung", "correct": false, "because": "Andere Technik"}, {"text": "Netzwerkgeschwindigkeit", "correct": false, "because": "Kein Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften hat ECC?', 5, '[{"text": "Fehlerkorrektur", "correct": true, "because": "Korrigiert Bitfehler"}, {"text": "Erkennung mehrerer Fehler", "correct": true, "because": "Mehrbit-Fehler"}, {"text": "Dauerhafte Speicherung", "correct": false, "because": "Nicht Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) ECC erhöht die Datenintegrität. b) Es macht Speicher schneller.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Leistung sekundär"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei ECC?', 4, '[{"text": "Fehlerkorrektur", "correct": false, "because": "Kernfunktion"}, {"text": "Speichergröße", "correct": false, "because": "Kapazität wichtig"}, {"text": "Gehäusefarbe", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ECC mehr Speicherplatz benötigt?', 2, '[{"text": "Ja", "correct": true, "because": "Zusätzliche Bits"}, {"text": "Nein", "correct": false, "because": "Paritätsbits nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Speicherart nutzt ECC häufig?', 3, '[{"text": "DRAM", "correct": true, "because": "ECC-RAM üblich"}, {"text": "SRAM", "correct": false, "because": "Weniger üblich"}, {"text": "Flash", "correct": false, "because": "Andere Technik"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ECC?', 5, '[{"text": "Datenintegrität", "correct": true, "because": "Fehler korrigieren"}, {"text": "Stabilität", "correct": true, "because": "Systemzuverlässigkeit"}, {"text": "Höhere Geschwindigkeit", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) ECC korrigiert Einzelbitfehler. b) Es ist in allen Speichern enthalten. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nicht Standard"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ECC?', 4, '[{"text": "ECC-fähiger Speicher", "correct": false, "because": "Hardware nötig"}, {"text": "Prozessorunterstützung", "correct": false, "because": "Kompatibilität"}, {"text": "Papierdokumentation", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ECC langsamer als nicht-ECC-Speicher?', 2, '[{"text": "Ja", "correct": true, "because": "Überprüfung kostet Zeit"}, {"text": "Nein", "correct": false, "because": "Leichter Overhead"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Systeme nutzen ECC typischerweise?', 4, '[{"text": "Server", "correct": true, "because": "Hohe Zuverlässigkeit"}, {"text": "Workstations", "correct": true, "because": "Datenintegrität"}, {"text": "Gaming-PCs", "correct": false, "because": "Weniger üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ECC nur für große Unternehmen ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleinere Systeme"}, {"text": "Ja", "correct": false, "because": "Breitere Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei ECC?', 3, '[{"text": "Datenintegrität", "correct": true, "because": "Fehler vermeiden"}, {"text": "Geschwindigkeit", "correct": false, "because": "Sekundär"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) ECC erkennt Mehrbitfehler. b) Es ist billiger als normaler RAM.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Teurer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Codes nutzt ECC?', 5, '[{"text": "Hamming-Code", "correct": true, "because": "Fehlerkorrektur"}, {"text": "Paritätsbits", "correct": true, "because": "Fehlererkennung"}, {"text": "Verschlüsselung", "correct": false, "because": "Kein ECC-Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei ECC unwichtig?', 3, '[{"text": "Fehlerkorrektur", "correct": false, "because": "Kernfunktion"}, {"text": "Kompatibilität", "correct": false, "because": "Hardwareabhängig"}, {"text": "Gewicht", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Benötigt ECC spezielle Hardware?', 3, '[{"text": "Ja", "correct": true, "because": "ECC-fähiger RAM"}, {"text": "Nein", "correct": false, "because": "Spezifische Unterstützung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ECC in allen PCs Standard ist?', 2, '[{"text": "Nein", "correct": true, "because": "Meist Server/Workstations"}, {"text": "Ja", "correct": false, "because": "Nicht Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature ist für ECC zentral?', 4, '[{"text": "Fehlerkorrektur", "correct": true, "because": "Kernmerkmal"}, {"text": "Hohe Geschwindigkeit", "correct": false, "because": "Nicht primär"}, {"text": "Dauerhafte Speicherung", "correct": false, "because": "Nicht Ziel"}]');
